const input = $input.first().json;

const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || input.trigger?.error || {};

const failedNode =
  execution.lastNodeExecuted ||
  error.node?.name ||
  "Unknown";

const executionId = execution.id || "Unknown";

const errorMessage =
  error.message ||
  error.description ||
  "Unknown error";

const errorType =
  error.httpCode ||
  error.statusCode ||
  error.code ||
  "UNKNOWN";

const messageText = String(errorMessage).toLowerCase();

let recoveryType = "PERMANENT";

if (
  messageText.includes("timeout") ||
  messageText.includes("connection") ||
  messageText.includes("closed unexpectedly") ||
  ["408", "429", "502", "503", "504"].includes(String(errorType))
) {
  recoveryType = "TRANSIENT";
}

return [
  {
    json: {
      event: "WORKFLOW_EXECUTION_FAILED",
      workflowId: workflow.id || "Unknown",
      workflowName: workflow.name || "Unknown",
      executionId,
      failedNode,
      errorMessage,
      errorType,
      recoveryType,
      incidentTime: new Date().toISOString(),
      dlqStatus: "PENDING"
    }
  }
];

const incident = $input.item.json;

const dlqRecord = {
  dlqId: `DLQ-${Date.now()}`,
  workflowName: incident.workflowName,
  executionId: incident.executionId,
  failedNode: incident.failedNode,
  errorMessage: incident.errorMessage,
  errorType: incident.errorType,
  recoveryType: incident.recoveryType,
  incidentTime: incident.incidentTime,
  dlqStatus: "PENDING",
  retryCount: 0,
  createdAt: new Date().toISOString()
};

return {
  json: dlqRecord
};

const item = $input.item.json;

return {
  json: {
    ...item,
    recoveryAction: "RETRY_SCHEDULED",
    dlqStatus: "PENDING_RETRY",
    retryCount: item.retryCount + 1,
    nextRetryAt: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
    message: "Temporary failure scheduled for retry after 5 minutes"
  }
};

const item = $input.item.json;

return {
  json: {
    ...item,
    recoveryAction: "ESCALATED_TO_ENGINEERING",
    dlqStatus: "ESCALATED",
    priority: "HIGH",
    assignedTeam: "Engineering Support",
    escalatedAt: new Date().toISOString(),
    message: "Permanent failure requires manual investigation"
  }
};

const item = $input.item.json;

return {
  json: {
    event: "RECOVERY_AUDIT",
    dlqId: item.dlqId,
    executionId: item.executionId,
    failedNode: item.failedNode,
    recoveryType: item.recoveryType,
    recoveryAction: item.recoveryAction,
    dlqStatus: item.dlqStatus,
    nextRetryAt: item.nextRetryAt || null,
    assignedTeam: item.assignedTeam || null,
    auditedAt: new Date().toISOString()
  }
};
